import * as $ from './js/recovery/jquery-3.6.0.min.js'

window.$ = $
let requireInstallApps = ''
// let timerData = null
let firstInitApps = false
window.uploadGroups = [
  {
    jarType: 'jar',
    zipType: 'zip',
    zipFileId: null,
    jarFileId: null,
    zipFileName: null,
    jarFileName: null
  }
]
let baseUrl = window.location.origin + '/api'
// 创建上传组
function createUploadGroup(group, index) {
  const showDeleteButton = group.jarType === 'jar'
  return `
                <div class="upload-group">
                    <div style="display: flex;flex-wrap: wrap;justify-content: center;"> 
                    <div class="upload-section">
                        <div class="upload-label">应用jar包</div>
                        <input type="file" id="${
                          group.jarType
                        }File" accept=".jar" style="display: none;">
                        <div class="upload-input">
                            <div id="${group.jarType}-file-name" class="upload-text"> ${
    group.jarFileName || ''
  }</div>
                            <div class="upload-clear" onclick="deleteJarFile('${index}','${
    group.jarType
  }')">×</div>
                        </div>
                        <button class="upload-btn" onclick="$('#${
                          group.jarType
                        }File').click()">点击上传</button>
                    </div>
                    <div class="upload-section">
                        <div class="upload-label">前端压缩包</div>
                        <input type="file" id="${
                          group.zipType
                        }File" accept=".zip" style="display: none;">
                        <div class="upload-input">
                            <div id="${group.zipType}-file-name" class="upload-text"> ${
    group.zipFileName || ''
  }</div>
                            <div class="upload-clear" onclick="deleteZipFile('${index}','${
    group.zipType
  }')">×</div>
                        </div>
                        <button class="upload-btn" onclick="$('#${
                          group.zipType
                        }File').click()">点击上传</button>
                    </div>
                    
                    </div>
                    <dvi class="add-btn-container">
                    ${
                      showDeleteButton
                        ? `<button class="add-btn" onclick="addNewUploadGroup()">+</button>`
                        : ''
                    } 
                    ${
                      !showDeleteButton
                        ? `<button class="del-btn" data-jar-type="${group.jarType}" onclick="deleteNewUploadGroup('${group.jarType}')">×</button>`
                        : ''
                    } 
                        </div>
                </div>
            `
}
// 删除jar包文件
function deleteJarFile(index, type) {
  uploadGroups[index].jarFileId = null
  uploadGroups[index].jarFileName = null
  $(`#${type}-file-name`).text('')
}
// 删除zip包文件
function deleteZipFile(index, type) {
  uploadGroups[index].zipFileId = null
  uploadGroups[index].zipFileName = null
  $(`#${type}-file-name`).text('')
}
// 渲染上传组
function renderUploadGroups() {
  const container = $('#uploadGroups')
  container.empty()
  uploadGroups.forEach((group, index) => {
    container.append(createUploadGroup(group, index))
    if (group.jarUploading) {
      $(`#${group.jarType}File`).siblings('.upload-btn').addClass('loading')
    }
    if (group.zipUploading) {
      $(`#${group.zipType}File`).siblings('.upload-btn').addClass('loading')
    }
  })
  checkUploadStatus()
  bindFileChangeEvents()
}
// 删除上传组确认提示
function deleteNewUploadGroup(type) {
  if (confirm('确定要删除这个上传吗？')) {
    uploadGroups = uploadGroups.filter((group) => group.jarType !== type)
    renderUploadGroups()
  }
}
// 上传组
function addNewUploadGroup() {
  const newGroup = {
    jarType: 'jar' + (uploadGroups.length + 1),
    zipType: 'zip' + (uploadGroups.length + 1),
    zipFileId: null,
    jarFileId: null,
    zipFileName: null,
    jarFileName: null,
    jarUploading: false,
    zipUploading: false
  }
  uploadGroups.push(newGroup)
  renderUploadGroups()
}
// 绑定文件选择事件
function bindFileChangeEvents() {
  uploadGroups.forEach((group, index) => {
    $(`#${group.jarType}File`)
      .off('change')
      .on('change', async function (e) {
        const file = e.target.files[0]
        if (file) {
          const $btn = $(this).siblings('.upload-btn')
          try {
            $btn.addClass('loading')
            uploadGroups[index].jarUploading = true
            checkUploadStatus()
            const response = await uploadFile(file, index, 'jar')
            if (JSON.parse(response).error) {
              alert(`上传失败: ${JSON.parse(response).error.message}`)
            } else {
              $(`#${group.jarType}-file-name`).text(file.name)
              uploadGroups[index].jarFileId = JSON.parse(response).result?.data?.[0]?.id || null
              uploadGroups[index].jarFileName = JSON.parse(response).result?.data?.[0]?.name || null
            }
          } catch (error) {
            alert(`上传失败: ${error}`)
          } finally {
            $btn.removeClass('loading')
            $(`#${group.jarType}File`).siblings('.upload-btn').removeClass('loading')
            uploadGroups[index].jarUploading = false
            checkUploadStatus()
          }
        }
      })
    $(`#${group.zipType}File`)
      .off('change')
      .on('change', async function (e) {
        const file = e.target.files[0]
        if (file) {
          const $btn = $(this).siblings('.upload-btn')
          try {
            $btn.addClass('loading')
            uploadGroups[index].zipUploading = true
            checkUploadStatus()
            const response = await uploadFile(file, index, 'zip')
            if (JSON.parse(response).error) {
              alert(`上传失败: ${JSON.parse(response).error.message}`)
            } else {
              $(`#${group.zipType}-file-name`).text(file.name)
              uploadGroups[index].zipFileId = JSON.parse(response).result?.data?.[0]?.id || null
              uploadGroups[index].zipFileName = JSON.parse(response).result?.data?.[0]?.name || null
            }
          } catch (error) {
            alert(`上传失败: ${error}`)
          } finally {
            $btn.removeClass('loading')
            $(`#${group.zipType}File`).siblings('.upload-btn').removeClass('loading')
            uploadGroups[index].zipUploading = false
            checkUploadStatus()
          }
        }
      })
  })
}
// 检查是否存在上传中的状态有则禁用删除按钮和提交按钮
function checkUploadStatus() {
  const hasUploading = uploadGroups.some(
    (group) => group.zipUploading === true || group.jarUploading === true
  )
  $('.submit-btn, .del-btn').prop('disabled', hasUploading)
}
// 清除cookie
function removeCookie(name) {
  document.cookie = name + '=; expires=Thu, 01 Jan 1970 00:00:00 UTC; path=/;'
}
// 清除登录信息，预防第二次更新最小镜像后，浏览器保存之前的登录信息
function clearLoginInfo() {
  try {
    localStorage.removeItem('userInfo')
    localStorage.removeItem('token')
    localStorage.removeItem('userInfoMore')
    localStorage.removeItem('userInfoMore')
    localStorage.removeItem('username')
    // sessionStorage.clear()
    removeCookie('userInfo')
    removeCookie('sieIiotToken')
  } catch (e) {
    console.error('清除登录信息失败', e)
  }
}

// 上传文件
function uploadFile(file, index, type) {
  return new Promise((resolve, reject) => {
    const formData = new FormData()
    formData.append('file', file)
    formData.append('bucketType', 'public')
    $.ajax({
      url: baseUrl + '/image/minimal/file/upload',
      method: 'POST',
      data: formData,
      processData: false,
      mimeType: 'multipart/form-data',
      contentType: false,
      success: function (response) {
        // console.log('上传成功:', response);
        resolve(response)
        // console.log('上传:', uploadGroups);
      },
      error: function (xhr, status, error) {
        // console.error('上传错误:', error);
        reject(error)
      }
    })
  })
}
// 提交
function submit() {
  let fileIds = []
  uploadGroups.map((item) => {
    if (item.jarFileId || item.zipFileId) {
      fileIds.push([item.jarFileId || '', item.zipFileId || ''])
    }
  })
  if (fileIds.length == 0) {
    alert('请先上传文件！')
    return
  }
  let paramsData = JSON.stringify({
    id: 'guid',
    jsonrpc: '2.0',
    method: 'service',
    params: {
      args: {
        serviceName: 'iidp-app',
        apps: fileIds,
        useDisplayForModel: true
      },
      context: {
        uid: '',
        timeZone: 'UTC+8',
        lang: 'zh-CN'
      },
      model: '',
      tag: 'master',
      service: '',
      app: 'base'
    }
  })
  $('.page-loading').addClass('active')
  setTimeout(() => {
    $('.page-loading').removeClass('active')
  }, 300000)
  $.ajax({
    url: baseUrl + '/image/minimal/requiredApps',
    method: 'POST',
    timeout: 0,
    data: paramsData,
    headers: {
      'Content-Type': 'application/json'
    },
    processData: false,
    contentType: false,
    success: function (response) {
      // 提交成功后跳转到其他页面
      if (response.error) {
        alert(response.error.data.debug)
      } else {
        // 先清除可能存在的登录信息
        clearLoginInfo()
        // 成功后跳转到登录页面
        window.location.href = window.location.origin + '/iidp/'
        //  alert('提交成功！');
        // verify()
        // if (!firstInitApps) {
        //   timerData = setInterval(function () {
        //     verify()
        //   }, 500)
        // }
      }
      $('.page-loading').removeClass('active')
    },
    error: function (xhr, status, error) {
      alert(response.error.data.debug)
      $('.page-loading').removeClass('active')
    },
    finally: function () {
      $('.page-loading').removeClass('active')
    }
  })
}
// 检查是否已经初始化完成和返回需要上传的app名
function verify() {
  $.ajax({
    url: baseUrl + '/image/minimal/config',
    method: 'GET',
    timeout: 0,
    headers: {
      'Content-Type': 'application/json'
    },
    success: function (response) {
      // console.log('verify', response?.result?.data?.firstInitApps)
      firstInitApps = response?.result?.data?.firstInitApps || false
      if (response?.result?.data?.firstInitApps) {
        // clearInterval(timerData)
        // timerData = null
        // 成功后跳转到登录页面
        window.location.href = window.location.origin + '/iidp/'
      }
      requireInstallApps = response?.result?.data?.requireInstallApps || ''
      $(`#submit-tips`).html(
        `注：根据您的版本配置，您需上传以下APP安装包进行提交\n${requireInstallApps}`.replace(
          /\n/g,
          '<br>'
        )
      )
    },
    error: function (xhr, status, error) {
      alert(response.error.data.debug)
    }
  })
}
// 窗口大小变化时重新计算高度
function setUploadGroupsMaxHeight() {
  const viewportHeight = window.innerHeight // 获取视口高度
  const paddingBottom = 170 // 预留底部空间（例如提交按钮区域的高度）
  const maxHeight = viewportHeight - paddingBottom // 计算最大高度
  $('.upload-groups').css('max-height', maxHeight + 'px')
}
// 窗口大小变化时重新计算高度
$(window).on('resize', function () {
  setUploadGroupsMaxHeight()
})
// window.addEventListener('beforeunload', function (e) {
//   if (timerData) {
//     clearInterval(timerData)
//   }
// })
$(document).ready(function () {
  setUploadGroupsMaxHeight()
  let tempApi = ''
  if (sessionStorage) {
    tempApi = sessionStorage.getItem('tempApi')
  }
  baseUrl = tempApi || baseUrl
  // 使用事件委托绑定添加按钮
  $(document).on('click', '.add-btn', function () {
    addNewUploadGroup()
  })
  $(document).on('click', '.submit-btn', function () {
    submit()
  })
  // 绑定删除按钮
  $(document).on('click', '.del-btn', function () {
    const type = $(this).closest('.upload-group').find('[data-jar-type]').data('jar-type')
    deleteNewUploadGroup(type)
  })
  verify()
  renderUploadGroups()
})
